/* Revolut DNA — midnight fintech, aurora gradient accents, borderless */
.theme-revolut-dna {
  --bg: oklch(0.189 0.014 278.6);
  --surface: oklch(0.229 0.020 275.9);
  --surface-2: oklch(0.271 0.025 274.5);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.670 0.022 267.2);
  --accent: oklch(0.572 0.226 282.0);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.653 0.168 260.1);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.615 0.190 27.8);
  --radius: 0.75rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Sora", sans-serif;
  --font-body: "Sora", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.05em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-revolut-dna h1,
.theme-revolut-dna h2,
.theme-revolut-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-revolut-dna { --font-ui: var(--font-display); background-image: radial-gradient(ellipse at 80% -10%, oklch(0.45 0.18 285 / 35%), transparent 50%); }
.theme-revolut-dna h1 { background: linear-gradient(95deg, var(--accent-2), var(--accent)); -webkit-background-clip: text; background-clip: text; color: transparent; }

/* depth */
.theme-revolut-dna td, .theme-revolut-dna th { font-variant-numeric: tabular-nums; }
.theme-revolut-dna thead th { font-size: 0.72rem; color: var(--fg-muted); letter-spacing: 0.05em; text-transform: uppercase; border-bottom: 1px solid var(--line); }
.theme-revolut-dna td { border-bottom: 1px solid oklch(1 0 0 / 7%); }
.theme-revolut-dna tbody tr:hover { background: var(--surface); }
.theme-revolut-dna input, .theme-revolut-dna select, .theme-revolut-dna textarea { background: var(--surface-2); border: 1px solid transparent; border-radius: var(--radius); transition: box-shadow 150ms ease, background 150ms ease; }
.theme-revolut-dna input:focus-visible, .theme-revolut-dna select:focus-visible, .theme-revolut-dna textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px color-mix(in oklab, var(--accent) 30%, transparent); background: var(--surface); }
.theme-revolut-dna a { color: var(--accent-2); text-decoration: none; font-weight: 600; }
.theme-revolut-dna a:hover { color: color-mix(in oklab, var(--accent-2) 70%, white); }
.theme-revolut-dna kbd { background: var(--surface-2); border: 1px solid var(--line); border-radius: var(--radius-sm); font-size: 0.75em; padding: 0.1em 0.45em; }
.theme-revolut-dna ::selection { background: color-mix(in oklab, var(--accent) 45%, transparent); }
.theme-revolut-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-revolut-dna ::-webkit-scrollbar-track { background: transparent; }
.theme-revolut-dna ::-webkit-scrollbar-thumb { background: oklch(1 0 0 / 20%); border-radius: var(--radius-pill); }
.theme-revolut-dna button { transition: filter 150ms ease, transform 150ms ease; }
.theme-revolut-dna button:hover { filter: brightness(1.15); }
.theme-revolut-dna button:active { transform: scale(0.98); }
.theme-revolut-dna .themed-border { border: 1px solid transparent; background-image: linear-gradient(var(--surface), var(--surface)), linear-gradient(120deg, oklch(0.65 0.2 285), oklch(0.7 0.15 250), oklch(0.75 0.12 200)); background-origin: border-box; background-clip: padding-box, border-box; }
.theme-revolut-dna .label-caps { color: var(--fg-muted); }

/* alt mode: auto-derived light variant */
.theme-revolut-dna.alt-mode {
  --bg: oklch(0.98 0.012 278.6);
  --surface: oklch(0.955 0.014 278.6);
  --surface-2: oklch(0.92 0.014 278.6);
  --fg: oklch(0.17 0.005 270);
  --fg-muted: oklch(0.46 0.01 270);
  --line: oklch(0.87 0.005 270);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: radial-gradient(ellipse at 80% -10%, oklch(0.85 0.07 285 / 55%), transparent 50%);
}
.theme-revolut-dna.alt-mode td { border-bottom-color: oklch(0 0 0 / 7%); }
.theme-revolut-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0 0 0 / 22%); }
.theme-revolut-dna.alt-mode a:hover { color: color-mix(in oklab, var(--accent-2) 70%, black); }
.theme-revolut-dna.alt-mode input, .theme-revolut-dna.alt-mode select, .theme-revolut-dna.alt-mode textarea { background: var(--surface-2); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
